#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_SIZE 16
#define BLOCK_SIZE 4

__global__ void matrix_mul_kernel(const float* A, const float* B, float* C, int N) {
    // Shared memory for tiles
    __shared__ float s_A[TILE_SIZE][TILE_SIZE];
    __shared__ float s_B[TILE_SIZE][TILE_SIZE];

    // Register block for each thread
    float reg_C[BLOCK_SIZE][BLOCK_SIZE] = {{0.0f}};

    int block_row = blockIdx.y * TILE_SIZE;
    int block_col = blockIdx.x * TILE_SIZE;

    int thread_row = threadIdx.y * BLOCK_SIZE;
    int thread_col = threadIdx.x * BLOCK_SIZE;

    // Loop over tiles
    for (int t = 0; t < (N + TILE_SIZE - 1) / TILE_SIZE; t++) {
        // Load tile from A into shared memory
        int t_col = t * TILE_SIZE + threadIdx.x;
        if (block_row + threadIdx.y < N && t_col < N) {
            s_A[threadIdx.y][threadIdx.x] = A[(block_row + threadIdx.y) * N + t_col];
        } else {
            s_A[threadIdx.y][threadIdx.x] = 0.0f;
        }

        // Load tile from B into shared memory
        int t_row = t * TILE_SIZE + threadIdx.y;
        if (t_row < N && block_col + threadIdx.x < N) {
            s_B[threadIdx.y][threadIdx.x] = B[t_row * N + (block_col + threadIdx.x)];
        } else {
            s_B[threadIdx.y][threadIdx.x] = 0.0f;
        }

        __syncthreads();

        // Compute partial sum with register blocking
        for (int k = 0; k < TILE_SIZE; k++) {
            // Prefetch values into registers
            float a_val[BLOCK_SIZE], b_val[BLOCK_SIZE];

            // Unroll inner loops
            #pragma unroll
            for (int i = 0; i < BLOCK_SIZE; i++) {
                a_val[i] = s_A[threadIdx.y + i][k];
            }

            #pragma unroll
            for (int j = 0; j < BLOCK_SIZE; j++) {
                b_val[j] = s_B[k][threadIdx.x + j];
            }

            // Multiply and accumulate
            #pragma unroll
            for (int i = 0; i < BLOCK_SIZE; i++) {
                #pragma unroll
                for (int j = 0; j < BLOCK_SIZE; j++) {
                    reg_C[i][j] += a_val[i] * b_val[j];
                }
            }
        }

        __syncthreads();
    }

    // Store result from register block to global memory
    for (int i = 0; i < BLOCK_SIZE; i++) {
        for (int j = 0; j < BLOCK_SIZE; j++) {
            int row = block_row + thread_row + i;
            int col = block_col + thread_col + j;
            if (row < N && col < N) {
                C[row * N + col] = reg_C[i][j];
            }
        }
    }
